application.css:
* {
  box-sizing: border-box;
}

:root {
  color: #172033;
  background: #f3f6fb;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.5;
}

body {
  margin: 0;
}

.page-shell {
  width: min(100% - 2rem, 52rem);
  margin: 0 auto;
  padding: 2.5rem 0;
}

.quiz-header {
  margin-bottom: 2rem;
}

.eyebrow {
  margin: 0 0 .35rem;
  color: #315ca8;
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
}

h1, h2, p {
  margin-top: 0;
}

h1 {
  margin-bottom: .5rem;
  font-size: clamp(2rem, 5vw, 3rem);
  line-height: 1.1;
}

.quiz-header p:last-child {
  margin-bottom: 0;
  color: #48566d;
}

.section-heading {
  font-size: 1.35rem;
}

.question-card {
  min-width: 0;
  margin: 0 0 1.25rem;
  padding: 1.25rem;
  border: 1px solid #cbd5e1;
  border-radius: .75rem;
  background: #fff;
}

legend {
  max-width: 100%;
  padding: 0 .35rem;
  font-weight: 700;
}

.options {
  display: grid;
  gap: .7rem;
  margin-top: 1rem;
}

.option {
  display: flex;
  align-items: center;
  gap: .7rem;
  min-height: 2.75rem;
  padding: .65rem .8rem;
  border: 1px solid #b7c3d4;
  border-radius: .45rem;
  cursor: pointer;
}

.option:hover {
  background: #f1f6ff;
  border-color: #315ca8;
}

.option:has(input:checked) {
  background: #e7efff;
  border-color: #244b91;
}

input {
  width: 1.1rem;
  height: 1.1rem;
  accent-color: #244b91;
}

button {
  border: 0;
  border-radius: .45rem;
  padding: .75rem 1.25rem;
  color: #fff;
  background: #244b91;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}

button:hover {
  background: #18386f;
}

button:focus-visible,
input:focus-visible,
.option:has(input:focus-visible) {
  outline: 3px solid #f2a900;
  outline-offset: 3px;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem;
  margin-top: 1.5rem;
}

.question-error,
.form-error {
  min-height: 1.4em;
  margin: .6rem 0 0;
  color: #a12727;
  font-size: .95rem;
  font-weight: 600;
}

.result {
  margin-top: 2rem;
  padding: 1.25rem;
  border-left: .35rem solid #315ca8;
  border-radius: .4rem;
  background: #fff;
}

.result h2 {
  margin-bottom: .35rem;
  font-size: 1.2rem;
}

.result p {
  margin-bottom: 0;
  font-size: 1.1rem;
  font-weight: 600;
}

@media (max-width:  thirtyrem) {
  .page-shell {
    width: min(100% - 1rem, 52rem);
    padding: 1.5rem 0;
  }
}

