const form = document.querySelector('#quiz-form');
const scoreElement = document.querySelector('[data-testid="quiz-score"]');
const formError = document.querySelector('#form-error');

const correctAnswers = Object.freeze({
  'question-1': 'html',
  'question-2': 'mars',
  'question-3': '12'
});

function getQuestionNames() {
  return Object.keys(correctAnswers);
}

function getSelectedAnswer(questionName) {
  const selected = form.querySelector(`input[name="${questionName}"]:checked`);
  return selected ? selected.value.trim() : '';
}

function clearMessages() {
  formError.textContent = '';
  form.querySelectorAll('.question-error').forEach((message) => {
    message.textContent = '';
  });
}

function validateAnswers() {
  let isValid = true;

  getQuestionNames().forEach((questionName, index) => {
    const error = form.querySelector(`#question-${index + 1}-error`);
    if (!getSelectedAnswer(questionName)) {
      error.textContent = 'Please select an answer.';
      isValid = false;
    }
  });

  if (!isValid) {
    formError.textContent = 'Complete all questions before submitting.';
  }

  return isValid;
}

function calculateScore() {
  return getQuestionNames().reduce((score, questionName) => {
    return score + (getSelectedAnswer(questionName) === correctAnswers[questionName] ? 1 : 0);
  }, 0);
}

function displayScore(score) {
  scoreElement.textContent = `You scored ${score} out of 3.`;
  scoreElement.dataset.score = String(score);
}

function handleSubmit(event) {
  event.preventDefault();
  clearMessages();

  if (!validateAnswers()) {
    const firstError = form.querySelector('.question-error:not(:empty)');
    if (firstError) {
      firstError.closest('.question-card').querySelector('input').focus();
    }
    return;
  }

  displayScore(calculateScore());
}

form.addEventListener('submit', handleSubmit);
